/**
 * One-time, production-only bootstrap for the four missing Hub read packages.
 * Package bodies are generated by the same builders used by the application.
 * The default mode is read-only; --publish writes only their derived GCS
 * objects and manifests. No Firestore write API is used here.
 */
import type { ReadPackageManifest, ReadPackageStore } from "@fika/server-shared/read-package";
const EXPECTED_PROJECT = "fika-os";
const EXPECTED_BUCKET = "fika-os-prod-read-packages-europe-west4";
const DATASETS = [
  "integration-hub/oplocs",
  "integration-hub/service-arrangements",
  "integration-hub/service-definitions",
  "integration-hub/authmod-references",
] as const;

function argument(name: string) {
  const index = process.argv.indexOf(name);
  return index < 0 ? undefined : process.argv[index + 1];
}

const publish = process.argv.includes("--publish");
const verify = process.argv.includes("--verify");
const project = argument("--project");
const bucketName = argument("--bucket");
if (process.argv.includes("--help")) {
  console.log("Usage: tsx scripts/bootstrap-production-read-packages.ts --project fika-os --bucket fika-os-prod-read-packages-europe-west4 [--publish | --verify]");
  process.exit(0);
}
if (project !== EXPECTED_PROJECT || bucketName !== EXPECTED_BUCKET) {
  throw new Error("Explicit production project and read-package bucket are required; staging/local targets are refused.");
}
if (publish && verify) throw new Error("Choose either --publish or --verify.");
if (process.env.FIRESTORE_EMULATOR_HOST || process.env.FIREBASE_AUTH_EMULATOR_HOST) {
  throw new Error("Emulator configuration is forbidden for this production-only command.");
}

process.env.FIKA_RUNTIME_MODE = "production";
process.env.FIREBASE_PROJECT_ID = EXPECTED_PROJECT;
process.env.GCLOUD_PROJECT = EXPECTED_PROJECT;
process.env.FIKA_SNAPSHOT_BUCKET = EXPECTED_BUCKET;
process.env.FIREBASE_STORAGE_BUCKET = EXPECTED_BUCKET;

const [adminApp, storageModule, readPackage, oplocBuilder, arrangementsBuilder, definitionsBuilder, authmodBuilder] = await Promise.all([
  import("firebase-admin/app"),
  import("firebase-admin/storage"),
  import("@fika/server-shared/read-package"),
  import("../lib/oploc-read-package"),
  import("../lib/service-arrangements-read-package"),
  import("../lib/service-definitions-read-package"),
  import("../lib/authmod-reference-read-package"),
]);

const app = adminApp.getApps().find(value => value.name === "[DEFAULT]") || adminApp.initializeApp({ projectId: EXPECTED_PROJECT, storageBucket: EXPECTED_BUCKET });
const bucket = storageModule.getStorage(app).bucket(EXPECTED_BUCKET);
const cloudStore: ReadPackageStore = {
  async putImmutable(name, bytes, contentHash) {
    const file = bucket.file(name);
    const [exists] = await file.exists();
    if (exists) {
      const [current] = await file.download({ decompress: false });
      if (readPackage.sha256(current) !== contentHash) throw new Error(`Existing immutable object differs: ${name}`);
      return;
    }
    await file.save(Buffer.from(bytes), {
      resumable: false,
      preconditionOpts: { ifGenerationMatch: 0 },
      metadata: { contentType: "application/json", contentEncoding: "gzip", metadata: { contentHash } },
    });
  },
  async get(name) {
    try { const [bytes] = await bucket.file(name).download({ decompress: false }); return bytes; }
    catch (error) { if ((error as { code?: number }).code === 404) return undefined; throw error; }
  },
  async has(name) { const [exists] = await bucket.file(name).exists(); return exists; },
  async getManifest(key) {
    try {
      const [bytes] = await bucket.file(`manifests/${key}.json`).download();
      return JSON.parse(bytes.toString("utf8")) as ReadPackageManifest;
    } catch (error) { if ((error as { code?: number }).code === 404) return undefined; throw error; }
  },
  async putManifest(key, manifest) {
    const file = bucket.file(`manifests/${key}.json`);
    const [exists] = await file.exists();
    if (exists) {
      const current = await this.getManifest(key);
      if (current?.contentHash !== manifest.contentHash || current?.objectName !== manifest.objectName || current?.sourceVersion !== manifest.sourceVersion) {
        throw new Error(`Existing package manifest differs: ${key}`);
      }
      return;
    }
    await file.save(JSON.stringify(manifest), {
      resumable: false,
      preconditionOpts: { ifGenerationMatch: 0 },
      metadata: { contentType: "application/json" },
    });
  },
};

const memoryStore = (): ReadPackageStore => {
  const objects = new Map<string, Uint8Array>();
  const manifests = new Map<string, ReadPackageManifest>();
  return {
    async putImmutable(name, bytes, hash) {
      if (readPackage.sha256(bytes) !== hash) throw new Error(`Builder supplied an invalid content hash: ${name}`);
      objects.set(name, Buffer.from(bytes));
    },
    async get(name) { const value = objects.get(name); return value && Buffer.from(value); },
    async has(name) { return objects.has(name); },
    async getManifest(name) { return manifests.get(name); },
    async putManifest(name, manifest) { manifests.set(name, manifest); },
  };
};

async function assertNoOrphans() {
  for (const dataset of DATASETS) {
    const [manifest, files] = await Promise.all([
      cloudStore.getManifest(dataset),
      bucket.getFiles({ prefix: `${dataset}/` }).then(([values]) => values),
    ]);
    if (manifest || files.length) throw new Error(`Preflight stopped: ${dataset} has an existing manifest or package object.`);
  }
}

async function verifyExisting() {
  const expectedContracts: Record<string, string> = {
    "integration-hub/oplocs": "integration-hub.oplocs.v2",
    "integration-hub/service-arrangements": "integration-hub.service-arrangements.v1",
    "integration-hub/service-definitions": "integration-hub.service-definitions.v1",
    "integration-hub/authmod-references": "integration-hub.authmod-references.v1",
  };
  const reports = [];
  for (const dataset of DATASETS) {
    const manifest = await cloudStore.getManifest(dataset);
    if (!manifest) throw new Error(`Verification failed: ${dataset} manifest is missing.`);
    const [bytes, listed] = await Promise.all([
      cloudStore.get(manifest.objectName),
      bucket.getFiles({ prefix: `${dataset}/` }).then(([files]) => files.map(file => file.name)),
    ]);
    if (!bytes) throw new Error(`Verification failed: ${dataset} object is missing.`);
    if (listed.length !== 1 || listed[0] !== manifest.objectName) throw new Error(`Verification failed: ${dataset} object prefix contains an unexpected set.`);
    if (manifest.contractVersion !== expectedContracts[dataset] || manifest.compressedSize !== bytes.byteLength || !manifest.objectName.endsWith(`${manifest.contentHash}.json.gz`)) {
      throw new Error(`Verification failed: ${dataset} manifest metadata does not match its object.`);
    }
    const decoded = readPackage.decodeReadPackage<Record<string, unknown>>(manifest, bytes);
    if (/fika-os-dev|staging/i.test(JSON.stringify(decoded))) throw new Error(`Verification failed: ${dataset} contains staging references.`);
    if (dataset === "integration-hub/authmod-references") {
      const value = decoded as { applications?: unknown[]; oplocs?: unknown[]; legends?: unknown[] };
      if (value.applications?.length !== 7 || value.oplocs?.length !== 19 || value.legends?.length !== 97 || manifest.recordCount !== 123 || manifest.sourceVersion !== "authmod-references:0:0:0") {
        throw new Error("Verification failed: AUTHMOD references differ from the approved production baseline.");
      }
    }
    reports.push({ dataset, packageVersion: manifest.packageVersion, recordCount: manifest.recordCount, objectName: manifest.objectName, contentHash: manifest.contentHash, compressedSize: bytes.byteLength, sourceVersion: manifest.sourceVersion, contractVersion: manifest.contractVersion });
  }
  console.log(JSON.stringify({ mode: "verify", project: EXPECTED_PROJECT, bucket: EXPECTED_BUCKET, packages: reports }, null, 2));
}

async function build(dataset: typeof DATASETS[number]) {
  const store = memoryStore();
  const manifest = dataset === "integration-hub/oplocs"
    ? await oplocBuilder.rebuildOplocReadPackage(store)
    : dataset === "integration-hub/service-arrangements"
      ? await arrangementsBuilder.rebuildServiceArrangementsReadPackage(store)
      : dataset === "integration-hub/service-definitions"
        ? await definitionsBuilder.rebuildServiceDefinitionsReadPackage(store)
        : await authmodBuilder.rebuildAuthmodReferenceReadPackage(store);
  const bytes = await store.get(manifest.objectName);
  if (!bytes) throw new Error(`Builder did not produce ${manifest.objectName}.`);
  const decoded = readPackage.decodeReadPackage<Record<string, unknown>>(manifest, bytes);
  return { dataset, manifest, bytes, decoded };
}

if (verify) {
  await verifyExisting();
  process.exit(0);
}

await assertNoOrphans();
const generated = [];
for (const dataset of DATASETS) generated.push(await build(dataset));

const authmod = generated.at(-1)!;
const authmodPayload = authmod.decoded as { applications?: unknown[]; oplocs?: unknown[]; legends?: unknown[] };
if (authmodPayload.applications?.length !== 7 || authmodPayload.oplocs?.length !== 19 || authmodPayload.legends?.length !== 97 || authmod.manifest.recordCount !== 123 || authmod.manifest.sourceVersion !== "authmod-references:0:0:0") {
  throw new Error("AUTHMOD references did not match the approved initial production baseline (7 applications, 19 active OPLOCs, 97 eligible Legends, source version 0:0:0).");
}

console.log(JSON.stringify({
  mode: publish ? "publish" : "dry-run",
  project: EXPECTED_PROJECT,
  bucket: EXPECTED_BUCKET,
  firestoreWrites: 0,
  packages: generated.map(({ dataset, manifest, decoded }) => ({
    dataset,
    packageVersion: manifest.packageVersion,
    recordCount: manifest.recordCount,
    objectName: manifest.objectName,
    contentHash: manifest.contentHash,
    compressedSize: manifest.compressedSize,
    sourceVersion: manifest.sourceVersion,
    contractVersion: manifest.contractVersion,
    ...(dataset === "integration-hub/authmod-references" ? {
      applications: (decoded as { applications: unknown[] }).applications.length,
      activeOplocs: (decoded as { oplocs: unknown[] }).oplocs.length,
      eligibleLegends: (decoded as { legends: unknown[] }).legends.length,
    } : {}),
  })),
}, null, 2));

if (publish) {
  for (const item of generated) {
    await readPackage.publishReadPackage(cloudStore, item.dataset, { manifest: item.manifest, bytes: item.bytes });
    const verified = await readPackage.retrieveReadPackage(cloudStore, item.dataset);
    if (!verified || verified.manifest.contentHash !== item.manifest.contentHash || verified.manifest.objectName !== item.manifest.objectName) {
      throw new Error(`Post-publication integrity verification failed: ${item.dataset}`);
    }
    console.log(`VERIFIED ${item.dataset} ${item.manifest.contentHash}`);
  }
}

export {};
